import React from "react";

export interface Column<T> {
  key: keyof T;
  header: string;
  render?: (value: T[keyof T], row: T) => React.ReactNode;
}

export interface DataTableProps<T> {
  columns: Column<T>[];
  rows: T[];
  rowKey: (row: T) => React.Key;
}

function DataTable<T>(props: DataTableProps<T>): JSX.Element {
  const { columns, rows, rowKey } = props;
  return (
    <table>
      <thead>
        <tr>
          {columns.map((col) => (
            <th key={String(col.key)}>{col.header}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={rowKey(row)}>
            {columns.map((col) => {
              const value: T[keyof T] = row[col.key];
              return (
                <td key={String(col.key)}>
                  {col.render ? col.render(value, row) : String(value)}
                </td>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export default DataTable;

import React from "react";

interface ListProps<T> {
  items: T[];
  renderItem: (item: T, index: number) => React.ReactNode;
  keyExtractor: (item: T) => React.Key;
  empty?: React.ReactNode;
}

const List = <T,>({ items, renderItem, keyExtractor, empty }: ListProps<T>): JSX.Element => {
  if (items.length === 0) {
    return <>{empty ?? null}</>;
  }
  return (
    <ul>
      {items.map((item, index) => (
        <li key={keyExtractor(item)}>{renderItem(item, index)}</li>
      ))}
    </ul>
  );
};

export default List;

import React from "react";

interface SelectOption {
  label: string;
  value: string | number;
}

interface GenericSelectProps<T extends SelectOption> {
  options: T[];
  value: T["value"] | null;
  onChange: (option: T) => void;
  placeholder?: string;
}

function GenericSelect<T extends SelectOption>(props: GenericSelectProps<T>): JSX.Element {
  const { options, value, onChange, placeholder } = props;

  const handleChange = (e: React.ChangeEvent<HTMLSelectElement>): void => {
    const selected = options.find((o) => String(o.value) === e.target.value);
    if (selected) onChange(selected);
  };

  return (
    <select value={value ?? ""} onChange={handleChange}>
      {placeholder && <option value="">{placeholder}</option>}
      {options.map((option) => (
        <option key={option.value} value={option.value}>
          {option.label}
        </option>
      ))}
    </select>
  );
}

export default GenericSelect;

