import React, { useMemo, useState } from "react";

interface AutocompleteProps<T> {
  items: T[];
  getLabel: (item: T) => string;
  onSelect: (item: T) => void;
  renderOption?: (item: T) => React.ReactNode;
}

const Autocomplete = <T,>({ items, getLabel, onSelect, renderOption }: AutocompleteProps<T>): JSX.Element => {
  const [query, setQuery] = useState<string>("");

  const filtered = useMemo<T[]>(
    () => items.filter((item) => getLabel(item).toLowerCase().includes(query.toLowerCase())),
    [items, query, getLabel]
  );

  return (
    <div className="autocomplete">
      <input
        value={query}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setQuery(e.target.value)}
      />
      <ul>
        {filtered.map((item, index) => (
          <li key={index} onClick={() => onSelect(item)}>
            {renderOption ? renderOption(item) : getLabel(item)}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Autocomplete;

import React, { useState } from "react";

type FormErrors<T> = Partial<Record<keyof T, string>>;

interface FormHelpers<T> {
  values: T;
  errors: FormErrors<T>;
  setField: <K extends keyof T>(key: K, value: T[K]) => void;
}

interface GenericFormProps<T extends Record<string, unknown>> {
  initialValues: T;
  validate?: (values: T) => FormErrors<T>;
  onSubmit: (values: T) => void;
  children: (helpers: FormHelpers<T>) => React.ReactNode;
}

function GenericForm<T extends Record<string, unknown>>(props: GenericFormProps<T>): JSX.Element {
  const { initialValues, validate, onSubmit, children } = props;
  const [values, setValues] = useState<T>(initialValues);
  const [errors, setErrors] = useState<FormErrors<T>>({});

  const setField = <K extends keyof T>(key: K, value: T[K]): void => {
    // 제네릭 객체 스프레드는 결과를 제약 타입으로 넓히므로 T로 단언한다.
    setValues((prev) => ({ ...prev, [key]: value }) as T);
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>): void => {
    e.preventDefault();
    const validationErrors = validate ? validate(values) : ({} as FormErrors<T>);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length === 0) {
      onSubmit(values);
    }
  };

  return <form onSubmit={handleSubmit}>{children({ values, errors, setField })}</form>;
}

export default GenericForm;

