}

function TreeView<T>({ nodes, renderNode }: TreeViewProps<T>): JSX.Element {
  return (
    <ul>
      {nodes.map((node, index) => (
        <li key={index}>
          {renderNode(node.value)}
          {node.children && node.children.length > 0 && (
            <TreeView nodes={node.children} renderNode={renderNode} />
          )}
        </li>
      ))}
    </ul>
  );
}

export default TreeView;

import { useCallback, useMemo, useState } from "react";
import type { Key } from "react";

interface UseSelectionResult<T> {
  selected: T[];
  isSelected: (item: T) => boolean;
  toggle: (item: T) => void;
  clear: () => void;
}

function useSelection<T>(getKey: (item: T) => Key): UseSelectionResult<T> {
  const [map, setMap] = useState<Map<Key, T>>(() => new Map<Key, T>());

  const toggle = useCallback(
    (item: T): void => {
      setMap((prev) => {
        const next = new Map<Key, T>(prev);
        const key = getKey(item);
        if (next.has(key)) {
          next.delete(key);
        } else {
          next.set(key, item);
        }
        return next;
      });
    },
    [getKey]
  );

  const isSelected = useCallback((item: T): boolean => map.has(getKey(item)), [map, getKey]);
  const clear = useCallback((): void => setMap(new Map<Key, T>()), []);
  const selected = useMemo<T[]>(() => Array.from(map.values()), [map]);

  return { selected, isSelected, toggle, clear };
}

export default useSelection;

import { useMemo, useState } from "react";

type SortDirection = "asc" | "desc";

interface UseSortableResult<T> {
  sorted: T[];
  sortKey: keyof T | null;
  direction: SortDirection;
  requestSort: (key: keyof T) => void;
}

function useSortable<T>(items: T[], initialKey: keyof T | null = null): UseSortableResult<T> {
  const [sortKey, setSortKey] = useState<keyof T | null>(initialKey);
  const [direction, setDirection] = useState<SortDirection>("asc");

  const requestSort = (key: keyof T): void => {
    if (key === sortKey) {
      setDirection((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setDirection("asc");
    }
  };

  const sorted = useMemo<T[]>(() => {
    if (sortKey === null) {
      return items;
    }
    const copy = [...items];
    copy.sort((a, b) => {
      const av = String(a[sortKey]);
      const bv = String(b[sortKey]);
      if (av < bv) return direction === "asc" ? -1 : 1;
      if (av > bv) return direction === "asc" ? 1 : -1;
      return 0;
    });
    return copy;
  }, [items, sortKey, direction]);

  return { sorted, sortKey, direction, requestSort };
}

export default useSortable;

import { useMemo, useState } from "react";

interface UsePaginationResult<T> {
  page: number;
  pageCount: number;
  pageItems: T[];
  setPage: (page: number) => void;
  next: () => void;
  prev: () => void;
}

function usePagination<T>(items: T[], pageSize: number): UsePaginationResult<T> {
  const [page, setPage] = useState<number>(1);

  const pageCount = Math.max(1, Math.ceil(items.length / pageSize));

  const pageItems = useMemo<T[]>(() => {
    const start = (page - 1) * pageSize;
    return items.slice(start, start + pageSize);
  }, [items, page, pageSize]);

  const next = (): void => setPage((p) => Math.min(pageCount, p + 1));
  const prev = (): void => setPage((p) => Math.max(1, p - 1));

  return { page, pageCount, pageItems, setPage, next, prev };
}

export default usePagination;

